cd /tmp/claude-0/-home-user/b7d31bcb-5d4a-54b3-81be-c137021a331c/scratchpad/ds-runs/083155bad1/analysis; python3 -I -c "
import sqlite3,math;c=sqlite3.connect('warehouse.db')
d={}
for w,p,k,s,cl in c.execute('select date>=\'2026-09-28\',platform,country,sum(searches),sum(clicks) from search_daily group by 1,2,3'):d[w,p+k]=(s,cl)
segs=sorted({k for _,k in d})
S0=sum(d[0,k][0] for k in segs)
def est(f):
  return f
# observed
def ctr(w):
  return sum(d[w,k][1] for k in segs)/sum(d[w,k][0] for k in segs)
var=lambda w:ctr(w)*(1-ctr(w))/sum(d[w,k][0] for k in segs)
o=ctr(1)-ctr(0);se=math.sqrt(var(0)+var(1));print('obs',o,o-1.96*se,o+1.96*se)
a=0;v=0
for k in segs:
  wt=d[0,k][0]/S0;p0=d[0,k][1]/d[0,k][0];p1=d[1,k][1]/d[1,k][0]
  a+=wt*(p1-p0);v+=wt**2*(p0*(1-p0)/d[0,k][0]+p1*(1-p1)/d[1,k][0])
  print(k,d[0,k][0]/S0,d[1,k][0]/sum(d[1,j][0] for j in segs))
print('adj',a,a-1.96*math.sqrt(v),a+1.96*math.sqrt(v))
"

